RestServiceDefinition.SqlExecute:



CREATE TABLE businessrole_page_offsets (
    PageOffset INTEGER
);

INSERT INTO businessrole_page_offsets (PageOffset)
WITH RECURSIVE pages(PageIndex) AS (
    SELECT 0
    UNION ALL
    SELECT PageIndex + 1
    FROM pages
    WHERE (PageIndex + 1) * $$BusinessRolesPageSize$$ < (
        SELECT CAST(COALESCE(MAX($$BusinessRolesRowCountColumn$$), 0) AS INTEGER)
        FROM businessrole_pageinfo
    )
)
SELECT PageIndex * $$BusinessRolesPageSize$$
FROM pages;

SELECT PageOffset FROM businessrole_page_offsets;
